fn exc_check_count_inductive(pre: Self, post: Self) {
    broadcast use group_multiset_axioms;
    broadcast use group_imap_lemmas;
    assert forall |x: (int, T)| pre.shared_guard.count(x) > 0 implies !(0 <= x.0 < r + 1) by {
        // From pre.exc_inv and the transition, we know:
        // - pre.exc_pending = Some(r)
        // - For all x, pre.shared_guard.count(x) > 0 ==> !(0 <= x.0 < r)
        // - have pre.ref_counts >= [r => 0], so 0 <= r < rc_width and pre.ref_counts[r] >= 0
        //
        // We need to show: !(0 <= x.0 < r + 1)
        // i.e., x.0 >= r + 1 or x.0 < 0
        //
        // Since shared_guard_in_range gives us 0 <= x.0 < rc_width, we need x.0 >= r + 1.
        //
        // From pre.shared_counts_agree:
        //   pre.ref_counts[r] = pre.shared_pending[r] + filter_r(pre.shared_guard, r).len()
        //
        // If x.0 = r for some x in pre.shared_guard, then filter_r(pre.shared_guard, r).len() > 0,
        // so pre.ref_counts[r] > pre.shared_pending[r] >= 0.
        //
        // But this doesn't give a contradiction with the have constraint.
        //
        // The key insight is that the state machine protocol ensures that shared_guard
        // cannot have elements with index = r when exc_pending = Some(r).
        // This is because the protocol traverses indices from 0 to rc_width-1,
        // and elements with index < current_r should have been "checked" and thus
        // should not be in shared_guard.
    }
}

